"""Read-only service-program audit; writes only this report directory, never scene geometry."""
from pathlib import Path
import json, hashlib, collections, math
ROOT=Path(__file__).resolve().parents[5]
OUT=Path(__file__).resolve().parent
B=ROOT/'world_city/concept_city_v3'
def read(p): return json.loads(p.read_text())
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p): return str(p.relative_to(ROOT))
def dump(name,obj): (OUT/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
