assert sha(P)=='685592393dd5b3bffa189d497db8bff14ba4d893d5d81089a66427bd5a6b588c'
assert sha(S)=='2d53ca4a99572f1a3383a847b6ae5f93dda78fb7e721af8a6a15b78de4d7f1c2'
plan=read(P); scene=read(S); original={x['id']:x for x in scene['common_instances']}; composed=dict(original)
index_path=B/'registered_integration/r9/integration_r02/index.json'; index=read(index_path)
packs=[]
for ref in index['packs']:
 p=ROOT/ref['path'];assert sha(p)==ref['sha256'];d=read(p)
 for i in d.get('remove_instance_ids',[]): composed.pop(i,None)
 for r in d.get('add_instances',[]):composed[r['id']]=r
 for r in d.get('replace_instances',[]):
  if 'id' in r:composed[r['id']]=r
 packs.append({'path':rel(p),'sha256':sha(p),'additions':len(d.get('add_instances',[])),'removals':len(d.get('remove_instance_ids',[]))})
