network=B/'registered_integration/r10_functional_audit/network'
water_access=read(network/'water_drawpoints.json') if (network/'water_drawpoints.json').exists() else []
logistics=read(network/'logistics_access_ledger.json') if (network/'logistics_access_ledger.json').exists() else []

def instances(ids=None,prefix=None):
 rows=[original[i] for i in ids] if ids else [v for k,v in original.items() if k.startswith(prefix)]
 return [{'id':r['id'],'asset_key':r['asset_key'],'position_xyz_m':r['position_m'],'yaw_rad':r['yaw_rad'],'evidence_status':'IMPLEMENTED_BASE_GEOMETRY'} for r in rows]
compound_ids=['CLERGY_CANONS_CLOSE','CLERGY_SCHOOL_SERVICE','CLERGY_GUEST_ALMS','R06_ABBEY_GATE_R05:herb','ABBEY_EAST_SERVICE','ABBEY_SOUTH_GARDEN_SERVICE']
compounds=[]
for id in compound_ids:
 r=original[id]; a=scene['common_assets'][r['asset_key']];p=ROOT/a['master_path']; assert sha(p)==a['master_sha256']; m=read(p)
 components=m['extensions'].get('existing_source_buildings',[])
 compounds.append({'runtime_instance_id':id,'asset_key':r['asset_key'],'position_xyz_m':r['position_m'],'source_master':rel(p),'source_master_sha256':sha(p),'component_role_prefixes':sorted(set(c['id'].split('__')[0] for c in m['components'])),'embedded_source_buildings':[{'id':x['id'],'function':x['function'],'source_position_xyz_m':x['position_m'],'role':x['role']} for x in components],'gate_source':m['extensions'].get('real_gate'),'status':'IMPLEMENTED_BASE_GEOMETRY; activity, staffing, admission and service capacity unverified'})
assert any('infirmary' in c['component_role_prefixes'] for c in compounds)
assert any('bakehouse' in c['component_role_prefixes'] for c in compounds)
assert any('almonry' in c['component_role_prefixes'] for c in compounds)

gardens=[]
for x in landscape['sites']:
 matches=[i for i in original if i.startswith(x['id']+':')]
 gardens.append({'id':x['id'],'space_id':x['space'],'kind':x['kind'],'source_frame_area_m2':x['area_m2'],'frame_center_xz_m':x['position'],'source_width_depth_m':[x['width'],x['depth']],'floor_y_m':x['floor'],'actual_prefix_instance_count':len(matches),'example_actual_ids':matches[:3],'area_status':'Authored allocated frame, not net cropped area or yield; not additive with overlapping later courts/frames.'})

